import{_ as t,o as i,c as a,a2 as s}from"./chunks/framework.CqpfiAoK.js";const p=JSON.parse('{"title":"Processus de Traitement des Trois Types de Vie Anomale","description":"","frontmatter":{},"headers":[],"relativePath":"fr/54-奇特生命三类处置流程.md","filePath":"fr/54-奇特生命三类处置流程.md"}'),n={name:"fr/54-奇特生命三类处置流程.md"};function r(o,e,d,l,u,m){return i(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="processus-de-traitement-des-trois-types-de-vie-anomale" tabindex="-1">Processus de Traitement des Trois Types de Vie Anomale <a class="header-anchor" href="#processus-de-traitement-des-trois-types-de-vie-anomale" aria-label="Permalink to &quot;Processus de Traitement des Trois Types de Vie Anomale&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Élément</th><th>Contenu</th></tr></thead><tbody><tr><td>N° de document</td><td>54</td></tr><tr><td>Module</td><td>Races et Formes de Vie</td></tr><tr><td>Mots clés</td><td>Symbiose amicale, observation et isolement, dissolution et transformation, processus de traitement, vie anomale</td></tr></tbody></table><h2 id="i-principes-generaux-du-processus-de-traitement" tabindex="-1">I. Principes Généraux du Processus de Traitement <a class="header-anchor" href="#i-principes-generaux-du-processus-de-traitement" aria-label="Permalink to &quot;I. Principes Généraux du Processus de Traitement&quot;">​</a></h2><p>Le traitement de la vie anomale est un maillon important de la gouvernance de la vie dans la Civilisation Symbiotique de l&#39;Ancre. Selon les résultats d&#39;évaluation des risques du <em>53-奇特生命识别标准</em>, le traitement de la vie anomale est divisé en trois types de processus normalisés : le type symbiose amicale, le type observation et isolement, et le type dissolution et transformation. Les trois types de processus correspondent respectivement aux niveaux de risque faible, moyen et élevé, formant un système de traitement complet, de l&#39;acceptation au contrôle puis à l&#39;élimination.</p><p>Le processus de traitement suit les principes généraux suivants :</p><table tabindex="0"><thead><tr><th>Principe</th><th>Contenu</th></tr></thead><tbody><tr><td>Principe de proportionnalité</td><td>L&#39;intensité des mesures de traitement doit correspondre au niveau de risque de la vie anomale ; le traitement excessif est interdit</td></tr><tr><td>Principe de procédure régulière</td><td>Le traitement doit être effectué selon les procédures légales, garantissant les droits fondamentaux de la vie anomale et le droit à l&#39;information des parties concernées</td></tr><tr><td>Principe de moindre préjudice</td><td>Dans la mesure où l&#39;objectif du traitement est atteint, réduire au maximum les préjudices à la vie anomale et à l&#39;environnement environnant</td></tr><tr><td>Principe de réversibilité</td><td>Prioriser les mesures de traitement réversibles, laissant de la place pour une réévaluation et un ajustement ultérieurs</td></tr><tr><td>Principe d&#39;enregistrement complet</td><td>L&#39;ensemble du processus de traitement est enregistré, formant une archive de traitement complète pour examen et traçabilité</td></tr></tbody></table><h2 id="ii-premier-type-processus-de-traitement-de-symbiose-amicale" tabindex="-1">II. Premier Type : Processus de Traitement de Symbiose Amicale <a class="header-anchor" href="#ii-premier-type-processus-de-traitement-de-symbiose-amicale" aria-label="Permalink to &quot;II. Premier Type : Processus de Traitement de Symbiose Amicale&quot;">​</a></h2><p>Le traitement de symbiose amicale s&#39;applique aux vies anomales identifiées et évaluées comme Premier niveau (risque faible), c&#39;est-à-dire les formes de vie ayant un niveau de conscience relativement élevé, aucune agressivité, un impact environnemental contrôlable et un potentiel symbiotique élevé.</p><h3 id="i-objectif-du-traitement" tabindex="-1">(I) Objectif du traitement <a class="header-anchor" href="#i-objectif-du-traitement" aria-label="Permalink to &quot;(I) Objectif du traitement&quot;">​</a></h3><p>Intégrer officiellement la vie anomale dans le système de la Civilisation Symbiotique de l&#39;Ancre, lui accorder un statut juridique et des droits fondamentaux égaux aux autres vies, l&#39;aider à s&#39;intégrer dans la société symbiotique et réaliser une évolution commune.</p><h3 id="ii-etapes-du-traitement" tabindex="-1">(II) Étapes du traitement <a class="header-anchor" href="#ii-etapes-du-traitement" aria-label="Permalink to &quot;(II) Étapes du traitement&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Étape</th><th>Nom</th><th>Contenu spécifique</th><th>Institution responsable</th></tr></thead><tbody><tr><td>Première étape</td><td>Établissement de la communication</td><td>Établir un canal de communication efficace avec la vie anomale pour comprendre son origine, ses besoins et ses souhaits</td><td>Bureau d&#39;Administration de la Vie + Groupe d&#39;experts en communication</td></tr><tr><td>Deuxième étape</td><td>Transmission du concept</td><td>Présenter à la vie anomale les concepts centraux, le système juridique et les normes sociales de la civilisation symbiotique</td><td>Ministère des Affaires Raciales + Institutions éducatives</td></tr><tr><td>Troisième étape</td><td>Enregistrement d&#39;identité</td><td>Effectuer l&#39;enregistrement d&#39;identité de la vie anomale, délivrer un certificat d&#39;identité de citoyen symbiotique et confirmer son statut juridique</td><td>Bureau d&#39;Administration de la Vie + Administration de l&#39;enregistrement des ménages</td></tr><tr><td>Quatrième étape</td><td>Attribution des droits</td><td>Accorder officiellement à la vie anomale tous les droits fondamentaux stipulés par la Constitution Symbiotique, y compris le droit de choisir l&#39;évolution, le droit d&#39;accès aux ressources, etc.</td><td>Comité Exécutif Symbiotique</td></tr><tr><td>Cinquième étape</td><td>Aide à l&#39;intégration</td><td>Fournir à la vie anomale des services d&#39;aide à l&#39;intégration tels que la formation linguistique, l&#39;adaptation culturelle et le guidage de culture</td><td>Institutions éducatives + Réseau de mentors</td></tr><tr><td>Sixième étape</td><td>Installation et résidence</td><td>Fournir des espaces de vie adaptés et des garanties de subsistance selon les caractéristiques physiologiques et les besoins de vie de la vie anomale</td><td>Administration du logement + Ministère des Affaires Raciales</td></tr><tr><td>Septième étape</td><td>Suivi et visites</td><td>Inclure dans la gestion sociale courante, effectuer des visites de suivi régulières pour comprendre la situation d&#39;intégration et résoudre rapidement les problèmes rencontrés</td><td>Communautés de base + Bureau d&#39;Administration de la Vie</td></tr></tbody></table><h3 id="iii-dispositions-speciales" tabindex="-1">(III) Dispositions spéciales <a class="header-anchor" href="#iii-dispositions-speciales" aria-label="Permalink to &quot;(III) Dispositions spéciales&quot;">​</a></h3><ul><li>Pour les vies anomales ayant des capacités ou des connaissances spéciales, elles peuvent être invitées à participer à la recherche et à la construction dans les domaines concernés, en exploitant leur valeur unique.</li><li>Pour les vies anomales provenant d&#39;autres plans ou univers, une assistance peut être fournie pour établir un contact avec leur habitat d&#39;origine, ou pour les aider à retourner dans leur habitat d&#39;origine (si tel est leur souhait).</li><li>Pour les vies anomales apparaissant en groupe, des communautés symbiotiques dédiées peuvent être établies pour aider à leur intégration collective.</li></ul><h3 id="iv-mecanisme-de-sortie" tabindex="-1">(IV) Mécanisme de sortie <a class="header-anchor" href="#iv-mecanisme-de-sortie" aria-label="Permalink to &quot;(IV) Mécanisme de sortie&quot;">​</a></h3><p>Si, au cours du processus d&#39;intégration, il s&#39;avère que le risque réel de la vie anomale est supérieur à l&#39;évaluation initiale, ou que son comportement menace l&#39;ordre symbiotique, une procédure de réévaluation peut être initiée et le type de traitement ajusté selon les résultats de la réévaluation.</p><h2 id="iii-deuxieme-type-processus-de-traitement-d-observation-et-d-isolement" tabindex="-1">III. Deuxième Type : Processus de Traitement d&#39;Observation et d&#39;Isolement <a class="header-anchor" href="#iii-deuxieme-type-processus-de-traitement-d-observation-et-d-isolement" aria-label="Permalink to &quot;III. Deuxième Type : Processus de Traitement d&#39;Observation et d&#39;Isolement&quot;">​</a></h2><p>Le traitement d&#39;observation et d&#39;isolement s&#39;applique aux vies anomales identifiées et évaluées comme Deuxième niveau (risque moyen), c&#39;est-à-dire les formes de vie ayant un niveau de conscience moyen, une certaine agressivité ou un certain impact environnemental, nécessitant guidage et surveillance.</p><h3 id="i-objectif-du-traitement-1" tabindex="-1">(I) Objectif du traitement <a class="header-anchor" href="#i-objectif-du-traitement-1" aria-label="Permalink to &quot;(I) Objectif du traitement&quot;">​</a></h3><p>Dans la mesure où la sécurité est assurée, effectuer une observation et un guidage continus de la vie anomale, réduire progressivement son niveau de risque et réaliser finalement une symbiose amicale ; pour celles dont le risque ne peut être réduit, maintenir un contrôle par isolement à long terme.</p><h3 id="ii-etapes-du-traitement-1" tabindex="-1">(II) Étapes du traitement <a class="header-anchor" href="#ii-etapes-du-traitement-1" aria-label="Permalink to &quot;(II) Étapes du traitement&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Étape</th><th>Nom</th><th>Contenu spécifique</th><th>Institution responsable</th></tr></thead><tbody><tr><td>Première étape</td><td>Isolement et placement</td><td>Transférer la vie anomale dans une installation dédiée d&#39;isolement et d&#39;observation, équipée de dispositifs de blindage énergétique, de stabilisation spatiale et de protection de sécurité</td><td>Bureau d&#39;Administration de la Vie + Équipe de traitement sur site</td></tr><tr><td>Deuxième étape</td><td>Observation continue</td><td>Effectuer une observation continue 24 heures sur 24 de la vie anomale, enregistrant ses modèles comportementaux, ses changements énergétiques et son activité consciente</td><td>Groupe d&#39;experts en identification + Équipe de surveillance</td></tr><tr><td>Troisième étape</td><td>Tentatives de communication</td><td>Sur la base de l&#39;observation, tenter d&#39;établir une communication avec la vie anomale pour comprendre ses motivations et besoins comportementaux</td><td>Groupe d&#39;experts en communication</td></tr><tr><td>Quatrième étape</td><td>Guidage comportemental</td><td>Par une combinaison d&#39;incitations positives et de contraintes négatives, guider la vie anomale vers des modèles comportementaux conformes aux normes symbiotiques</td><td>Experts comportementaux + Cultivateurs</td></tr><tr><td>Cinquième étape</td><td>Réévaluation du risque</td><td>Effectuer une réévaluation du risque tous les trois mois, ajustant le niveau de risque selon les résultats d&#39;observation et de guidage</td><td>Groupe d&#39;experts en identification</td></tr><tr><td>Sixième étape</td><td>Ouverture progressive</td><td>Selon le degré de réduction du risque, élargir progressivement la portée d&#39;activité et les permissions de contact de la vie anomale, de l&#39;isolement complet à l&#39;ouverture limitée</td><td>Bureau d&#39;Administration de la Vie</td></tr><tr><td>Septième étape</td><td>Conversion de type</td><td>Si le niveau de risque descend au Premier niveau, convertir en traitement de symbiose amicale ; s&#39;il monte au Troisième niveau, convertir en traitement de dissolution et de transformation</td><td>Bureau d&#39;Administration de la Vie + Tribunal de la Vie Anomale</td></tr></tbody></table><h3 id="iii-normes-des-installations-d-isolement" tabindex="-1">(III) Normes des installations d&#39;isolement <a class="header-anchor" href="#iii-normes-des-installations-d-isolement" aria-label="Permalink to &quot;(III) Normes des installations d&#39;isolement&quot;">​</a></h3><ul><li><strong>Normes spatiales</strong> : la taille de l&#39;espace d&#39;isolement est déterminée selon la taille corporelle et les besoins d&#39;activité de la vie anomale, avec un minimum non inférieur à dix fois sa taille corporelle.</li><li><strong>Normes énergétiques</strong> : équiper de dispositifs de blindage et de régulation énergétiques pour empêcher les fuites d&#39;énergie de la vie anomale ou les interférences énergétiques extérieures.</li><li><strong>Normes de sécurité</strong> : équiper de multiples dispositifs de protection de sécurité, y compris des barrières physiques, des barrières énergétiques et des verrouillages spatiaux, pour garantir que la vie anomale ne puisse pas franchir l&#39;isolement.</li><li><strong>Normes de surveillance</strong> : équiper d&#39;équipements de surveillance complets pour surveiller en temps réel les signes vitaux, les fluctuations énergétiques et les activités comportementales de la vie anomale.</li><li><strong>Normes environnementales</strong> : fournir des conditions environnementales adaptées selon les besoins physiologiques de la vie anomale, y compris la température, l&#39;humidité et la concentration d&#39;énergie.</li></ul><h3 id="iv-gestion-de-l-isolement-a-long-terme" tabindex="-1">(IV) Gestion de l&#39;isolement à long terme <a class="header-anchor" href="#iv-gestion-de-l-isolement-a-long-terme" aria-label="Permalink to &quot;(IV) Gestion de l&#39;isolement à long terme&quot;">​</a></h3><p>Pour les vies anomales qui ne peuvent réduire leur niveau de risque même après une observation et un guidage à long terme, une gestion d&#39;isolement à long terme est mise en œuvre :</p><ul><li>Les vies anomales en isolement à long terme jouissent de droits fondamentaux de sécurité de vie, y compris un environnement de vie adapté, un approvisionnement énergétique nécessaire et des soins médicaux.</li><li>Les installations d&#39;isolement à long terme doivent être régulièrement inspectées et entretenues pour garantir la sécurité et l&#39;adéquation de l&#39;isolement.</li><li>Une évaluation complète des vies anomales en isolement à long terme est effectuée chaque année pour confirmer s&#39;il existe une possibilité d&#39;ajuster le type de traitement.</li><li>Si les vies anomales en isolement à long terme expriment le souhait de dissolution ou de transformation volontaire, ce souhait doit être respecté et une assistance correspondante fournie.</li></ul><h2 id="iv-troisieme-type-processus-de-traitement-de-dissolution-et-de-transformation" tabindex="-1">IV. Troisième Type : Processus de Traitement de Dissolution et de Transformation <a class="header-anchor" href="#iv-troisieme-type-processus-de-traitement-de-dissolution-et-de-transformation" aria-label="Permalink to &quot;IV. Troisième Type : Processus de Traitement de Dissolution et de Transformation&quot;">​</a></h2><p>Le traitement de dissolution et de transformation s&#39;applique aux vies anomales identifiées et évaluées comme Troisième niveau (risque élevé), c&#39;est-à-dire les formes de vie ayant un niveau de conscience faible ou malveillant, une forte agressivité, des dommages environnementaux graves et un faible potentiel symbiotique. Les vies anomales de Quatrième niveau (risque extrêmement élevé) relèvent de la procédure de dissolution d&#39;urgence.</p><h3 id="i-objectif-du-traitement-2" tabindex="-1">(I) Objectif du traitement <a class="header-anchor" href="#i-objectif-du-traitement-2" aria-label="Permalink to &quot;(I) Objectif du traitement&quot;">​</a></h3><p>Par la dissolution ou la transformation, éliminer la menace de la vie anomale pour l&#39;ordre symbiotique, tout en convertissant son énergie et sa matière en ressources bénéfiques autant que possible, réalisant « transformer le mal en bien ».</p><h3 id="ii-methodes-de-traitement" tabindex="-1">(II) Méthodes de traitement <a class="header-anchor" href="#ii-methodes-de-traitement" aria-label="Permalink to &quot;(II) Méthodes de traitement&quot;">​</a></h3><p>Le traitement de dissolution et de transformation est divisé en deux méthodes, choisies selon les circonstances spécifiques de la vie anomale :</p><table tabindex="0"><thead><tr><th>Méthode</th><th>Nom</th><th>Situation applicable</th><th>Méthode spécifique</th></tr></thead><tbody><tr><td>Méthode 1</td><td>Dissolution d&#39;énergie</td><td>Vies anomales ne pouvant être transformées ou dont le risque de transformation est trop élevé</td><td>Utiliser des dispositifs ou des sorts de dissolution dédiés pour décomposer l&#39;énergie et la matière de la vie anomale en particules fondamentales, les retournant à l&#39;Origine de l&#39;univers</td></tr><tr><td>Méthode 2</td><td>Transformation bénigne</td><td>Vies anomales pouvant être transformées et dont le risque post-transformation est contrôlable</td><td>Par la reconstruction énergétique, la purification de la conscience, le remodelage de la forme, etc., transformer la vie anomale en formes de vie ou ressources énergétiques inoffensives ou bénéfiques</td></tr></tbody></table><h3 id="iii-etapes-du-traitement" tabindex="-1">(III) Étapes du traitement <a class="header-anchor" href="#iii-etapes-du-traitement" aria-label="Permalink to &quot;(III) Étapes du traitement&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Étape</th><th>Nom</th><th>Contenu spécifique</th><th>Institution responsable</th></tr></thead><tbody><tr><td>Première étape</td><td>Approbation du traitement</td><td>La dissolution et la transformation des vies anomales à haut risque doivent être soumises à l&#39;examen judiciaire et à l&#39;approbation du Tribunal de la Vie Anomale ; pour le risque extrêmement élevé, le traitement peut précéder l&#39;approbation rétroactive</td><td>Tribunal de la Vie Anomale</td></tr><tr><td>Deuxième étape</td><td>Élaboration du plan</td><td>Élaborer un plan détaillé de dissolution et de transformation, y compris les méthodes de traitement, les moyens techniques, les mesures de sécurité et les plans d&#39;urgence</td><td>Bureau d&#39;Administration de la Vie + Groupe d&#39;experts techniques</td></tr><tr><td>Troisième étape</td><td>Isolement de sécurité</td><td>Transférer la vie anomale dans une installation dédiée de dissolution et de transformation, équipée du plus haut niveau de protection de sécurité et de dispositifs de confinement de l&#39;énergie</td><td>Équipe de traitement sur site</td></tr><tr><td>Quatrième étape</td><td>Dissolution et transformation</td><td>Mettre en œuvre la dissolution et la transformation selon le plan, avec le processus complet surveillé ; en cas d&#39;anomalie, activer immédiatement le plan d&#39;urgence</td><td>Groupe d&#39;experts techniques + Cultivateurs</td></tr><tr><td>Cinquième étape</td><td>Traitement des produits</td><td>Tester et traiter l&#39;énergie et la matière produites par la dissolution et la transformation ; les éléments utilisables sont intégrés aux réserves de ressources, les éléments nocifs subissent une élimination sûre</td><td>Administration des ressources</td></tr><tr><td>Sixième étape</td><td>Restauration environnementale</td><td>Restaurer l&#39;environnement affecté pendant le processus de traitement, rétablissant l&#39;équilibre écologique et énergétique</td><td>Ministère de l&#39;Écologie et de l&#39;Environnement</td></tr><tr><td>Septième étape</td><td>Archivage</td><td>Organiser et archiver les enregistrements, données et rapports de l&#39;ensemble du processus de traitement, formant une archive de traitement complète</td><td>Bureau d&#39;Administration de la Vie</td></tr></tbody></table><h3 id="iv-procedure-de-dissolution-d-urgence" tabindex="-1">(IV) Procédure de dissolution d&#39;urgence <a class="header-anchor" href="#iv-procedure-de-dissolution-d-urgence" aria-label="Permalink to &quot;(IV) Procédure de dissolution d&#39;urgence&quot;">​</a></h3><p>Pour les vies anomales de Quatrième niveau (risque extrêmement élevé), c&#39;est-à-dire les vies anomales ayant un pouvoir destructeur de niveau cosmique, ne pouvant communiquer, incontrôlables et menaçant directement la survie de la civilisation, la procédure de dissolution d&#39;urgence s&#39;applique :</p><ol><li>La personne du plus haut rang sur place peut directement ordonner le déclenchement de la dissolution d&#39;urgence sans approbation préalable, mais doit déposer un rapport au Tribunal de la Vie Anomale dans les 24 heures suivant le traitement.</li><li>La dissolution d&#39;urgence peut mobiliser les forces et ressources énergétiques du plus haut niveau de la civilisation, y compris l&#39;action conjointe des Puissances Suprêmes du Plan.</li><li>L&#39;objectif prioritaire de la dissolution d&#39;urgence est d&#39;éliminer la menace et de protéger la sécurité de la vie et de la civilisation, sans rechercher « transformer le mal en bien ».</li><li>Après la dissolution d&#39;urgence, une évaluation et une restauration environnementales complètes doivent être effectuées pour prévenir les catastrophes secondaires.</li></ol><h3 id="v-contraintes-ethiques" tabindex="-1">(V) Contraintes éthiques <a class="header-anchor" href="#v-contraintes-ethiques" aria-label="Permalink to &quot;(V) Contraintes éthiques&quot;">​</a></h3><p>Le traitement de dissolution et de transformation implique la fin de la vie et doit être soumis à de strictes contraintes éthiques :</p><ul><li>La dissolution et la transformation doivent être le dernier recours, adoptées seulement lorsque ni la symbiose amicale ni l&#39;observation et l&#39;isolement ne sont possibles.</li><li>Pour les vies anomales ayant conscience et émotions, la dissolution doit adopter une méthode sans douleur et rapide autant que possible pour réduire leur souffrance.</li><li>Il est interdit de se livrer au pillage au nom de la dissolution et de la transformation ; l&#39;énergie et la matière des vies anomales ne doivent pas être appropriées comme propriété privée.</li><li>Les décisions de dissolution et de transformation doivent subir un strict examen judiciaire pour prévenir l&#39;abus de pouvoir.</li><li>Effectuer une analyse sommaire annuelle des cas de dissolution et de transformation, évaluer la nécessité et la rationalité des traitements et améliorer continuellement les normes d&#39;identification et de traitement.</li></ul><h2 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h2><p>Le processus de traitement des trois types de vies anomales est le système opérationnel normalisé de la gouvernance de la vie dans la Civilisation Symbiotique de l&#39;Ancre. De l&#39;acceptation ouverte de la symbiose amicale, au contrôle prudent de l&#39;observation et de l&#39;isolement, jusqu&#39;au dernier recours de la dissolution et de la transformation, les trois types de processus forment une chaîne complète de réponse aux risques. Ils incarnent le respect et l&#39;inclusion de la vie par la civilisation symbiotique tout en défendant la ligne de base de la protection de la sécurité civilisationnelle, réalisant l&#39;équilibre de gouvernance « ouvert sans céder du terrain, inclusif sans complaisance ».</p><h2 id="documents-connexes" tabindex="-1">Documents Connexes <a class="header-anchor" href="#documents-connexes" aria-label="Permalink to &quot;Documents Connexes&quot;">​</a></h2><ul><li>53-奇特生命识别标准 (Normes d&#39;Identification de la Vie Anomale)</li><li>56-奇异能量三类处置流程 (Processus de Traitement des Trois Types d&#39;Énergie Anomale)</li><li>59-黑暗置换体四类分支处置 (Traitement des Quatre Branches des Entités de Remplacement Sombres)</li><li>48-司法体系与裁决机制 (Système Judiciaire et Mécanisme d&#39;Arbitrage)</li></ul>',46)])])}const v=t(n,[["render",r]]);export{p as __pageData,v as default};
